  const addEdge=(source,target,relation)=>edges.push({source,target,relation});
  addNode(ins.id,'instrument',ins.id,{type:ins.type,serial:ins.serial,status:ins.status});
  if(ins.ownerId){const u=data.users.find(x=>x.id===ins.ownerId);addNode(ins.ownerId,'owner',u?.organization||u?.name||ins.ownerName||ins.ownerId,{role:u?.role||'business'});addEdge(ins.ownerId,ins.id,'OWNS');}
